const STORE="willow-table-round-v1",$=s=>document.querySelector(s);let state,botTimer,generation=0;
const seatTitle=i=>["You · East","South","West","North"][i];
function newGame(){cancelBot();const wall=createWall(),players=Array.from({length:4},()=>({hand:[],melds:[],discards:[]}));for(let r=0;r<13;r++)for(const p of players)p.hand.push(wall.pop());players[0].hand.push(wall.pop());state={wall,players,turn:0,phase:"discard",lastDiscard:null,lastDiscarder:null,turnStartedByDraw:true,message:"Your opening turn. Select a tile to discard.",result:null};commit()}
function cancelBot(){generation++;clearTimeout(botTimer)}
function save(){localStorage.setItem(STORE,JSON.stringify(state));$("#save-status").textContent="Saved locally"}
function commit(){save();render();resume()}
function load(){try{state=JSON.parse(localStorage.getItem(STORE))}catch{}if(!state?.players?.length)newGame();else{render();resume()}}
