import { createWall,sortTiles,tileInfo,tileShortLabel,tileClass,tileLabel,chooseDiscard } from "./game.js";
import { canSelfDraw,claimChoices,settleClaims,applySettlement,discardTransition,drawTransition } from "./transitions.js";
const STORE="willow-table-round-v1",PREFERENCES="willow-table-preferences-v1",$=s=>document.querySelector(s);
let state,botTimer,generation=0,selectedTile=null,preferences={speed:"normal",tileText:"standard",motion:"system"},focusTarget=null;
const seatTitle=i=>["You · East","South","West","North"][i],speedDelay={slow:1200,normal:650,fast:250};
function newGame(){cancelBot();const wall=createWall(),players=Array.from({length:4},()=>({hand:[],melds:[],discards:[],discardHistory:[]}));for(let r=0;r<13;r++)for(const p of players)p.hand.push(wall.pop());players[0].hand.push(wall.pop());selectedTile=null;state={wall,players,turn:0,phase:"discard",lastDiscard:null,lastDiscarder:null,turnStartedByDraw:true,message:"Your opening turn. Select a tile, then press Discard selected tile.",result:null};focusTarget="hand";commit()}
function cancelBot(){generation++;clearTimeout(botTimer)}
function save(){localStorage.setItem(STORE,JSON.stringify(state));$("#save-status").textContent="Saved locally"}
function savePreferences(){localStorage.setItem(PREFERENCES,JSON.stringify(preferences));$("#save-status").textContent="Settings saved locally"}
function applyPreferences(){document.documentElement.dataset.tileText=preferences.tileText;document.documentElement.dataset.motion=preferences.motion;$("#computer-speed").value=preferences.speed;$("#tile-text").value=preferences.tileText;$("#reduced-motion").value=preferences.motion}
function loadPreferences(){try{preferences={...preferences,...JSON.parse(localStorage.getItem(PREFERENCES))}}catch{}applyPreferences()}
function commit(){save();render();resume()}
function load(){try{state=JSON.parse(localStorage.getItem(STORE))}catch{}if(!state?.players?.length)newGame();else{state.players.forEach(p=>p.discardHistory??=[...p.discards]);render();resume()}}
function hasUserClaim(){const c=claimChoices(state,0);return c.ron||c.pon||c.chi.length}function resume(){if(state.phase==="draw"&&state.turn===0)draw();else if((state.phase==="draw"||state.phase==="discard")&&state.turn!==0)scheduleBot();else if(state.phase==="claim"&&(state.lastDiscarder===0||!hasUserClaim()))scheduleSettlement()}
function tileHtml(t,small=false,button=false){const d=tileInfo(t),cls=`tile ${small?"mini-tile":""} ${tileClass(t)} ${selectedTile===t?"selected":""}`,body=`<span class="tile-rank">${d.honor?tileShortLabel(t):d.rank}</span><span class="tile-suit">${d.honor?"honor":({m:"char",p:"dots",s:"bamboo"})[d.suit]}</span>`;return button?`<button class="${cls}" data-tile="${t}" aria-label="${tileLabel(t)}${selectedTile===t?", selected":""}" aria-pressed="${selectedTile===t}">${body}</button>`:`<span class="${cls}" title="${tileLabel(t)}">${body}</span>`}
const melds=m=>m.map(x=>`<span class="meld">${x.map(t=>tileHtml(t,true)).join("")}</span>`).join("");
function historyHtml(p){const history=p.discardHistory??p.discards;return `<details class="discard-history"><summary>Discards (${history.length})</summary><div>${history.length?history.map(t=>tileHtml(t,true)).join(""):"No discards yet."}</div></details>`}
function renderOpponent(i){const p=state.players[i],el=$(`#seat-${i}`),active=state.turn===i&&state.phase!=="ended";el.className=`opponent ${["","south","west","north"][i]} ${active?"active":""}`;el.innerHTML=`<div class="seat-heading"><i class="seat-dot"></i><span>${seatTitle(i)} · ${p.hand.length} concealed</span></div><div class="opponent-hand">${Array.from({length:p.hand.length},()=>'<i class="back-tile"></i>').join("")}</div><div class="exposed">${melds(p.melds)}</div>${historyHtml(p)}`}
function renderPlayer(){const p=state.players[0],can=state.turn===0&&state.phase==="discard",tiles=sortTiles(p.hand);if(!tiles.includes(selectedTile))selectedTile=null;$("#seat-0").innerHTML=`<div class="player-heading"><strong><i class="seat-dot"></i> You · East</strong><span>${p.hand.length} concealed</span></div><div class="exposed">${melds(p.melds)}</div><div class="hand" role="group" aria-label="Your hand; use arrow keys, Home and End to select a tile">${tiles.map(t=>tileHtml(t,false,can)).join("")}</div>${historyHtml(p)}`;document.querySelectorAll(".hand button[data-tile]").forEach(b=>b.onclick=()=>{selectedTile=b.dataset.tile;focusTarget="selected";render()})}
function restoreFocus(){const target=focusTarget;focusTarget=null;if(target==="hand"||target==="selected")requestAnimationFrame(()=>document.querySelector(`.hand button[data-tile="${selectedTile}"]`)?.focus()||document.querySelector(".hand button")?.focus());else if(target==="claim")requestAnimationFrame(()=>$("#claim-controls button")?.focus());else if(target==="discard")requestAnimationFrame(()=>$("#discard-selected")?.focus())}
function render(){for(let i=1;i<4;i++)renderOpponent(i);renderPlayer();$("#round-label").textContent=state.result?"HAND COMPLETE":`EAST ROUND · ${state.phase==="claim"?"CLAIM WINDOW":seatTitle(state.turn).toUpperCase()}`;const last=$("#last-discard");last.className=`last-discard ${state.lastDiscard?tileClass(state.lastDiscard):"empty"}`;last.innerHTML=state.lastDiscard?tileHtml(state.lastDiscard):"—";$("#table-message").textContent=state.message;$("#wall-count").textContent=`${state.wall.length} tiles left in wall`;controls();restoreFocus()}
function controls(){const claim=$("#claim-controls"),turn=$("#turn-controls");claim.innerHTML=turn.innerHTML="";if(state.phase==="claim"&&state.lastDiscarder!==0){const c=claimChoices(state,0);if(c.ron)claim.innerHTML+='<button class="action-button warn" data-claim="ron">Ron — win with this discard</button>';if(c.pon)claim.innerHTML+='<button class="action-button" data-claim="pon">Pon — make a matching triple</button>';c.chi.forEach((o,i)=>claim.innerHTML+=`<button class="action-button" data-claim="chi" data-option="${i}">Chi — make a run with ${o.map(tileShortLabel).join(" and ")}</button>`);claim.innerHTML+='<button class="action-button secondary" data-claim="pass">Pass — do not claim</button>';claim.querySelectorAll("button").forEach(b=>b.onclick=()=>userClaim(b.dataset.claim,Number(b.dataset.option)));focusTarget="claim"}if(state.phase==="ended")turn.innerHTML='<button class="action-button" id="again">Deal a new hand</button>';else if(canSelfDraw(state,0))turn.innerHTML='<button class="action-button warn" id="tsumo">Self-draw win</button>';else if(state.turn!==0||state.phase==="draw")turn.innerHTML='<span class="control-copy">Computer players are thinking…</span>';else turn.innerHTML=`<button id="discard-selected" class="action-button" ${selectedTile?"":"disabled"}>Discard selected tile${selectedTile?`: ${tileLabel(selectedTile)}`:""}</button><span class="control-copy">Select a tile, then discard it.</span>`;$("#discard-selected")?.addEventListener("click",()=>discard(0,selectedTile));$("#again")?.addEventListener("click",newGame);$("#tsumo")?.addEventListener("click",()=>finish("You win by self-draw."))}
function finish(msg){cancelBot();selectedTile=null;state.phase="ended";state.result=msg;state.message=msg;save();render()}
function discard(seat,tile){const next=discardTransition(state,seat,tile);if(!next)return;selectedTile=null;state=next;state.message=`${seatTitle(seat)} discarded ${tileLabel(tile)}. Checking claims…`;save();render();if(seat===0)scheduleSettlement()}
function settle(choice=null){if(state.phase!=="claim")return;const outcome=settleClaims(state,choice);if(!outcome)return;const winningTile=state.lastDiscard;const next=applySettlement(state,outcome);if(!next)return;state=next;if(state.phase==="ended")state.message=`${seatTitle(outcome.seat)} wins by Ron on ${tileLabel(winningTile)}.`;else state.message=outcome.kind==="claim"?`${seatTitle(outcome.seat)} claimed ${outcome.type}.`:`${seatTitle(state.turn)} draws a tile.`;focusTarget=state.turn===0?"hand":null;commit()}
function userClaim(type,option){settle(type==="pass"?null:{type,option})}
function draw(){const next=drawTransition(state);if(!next)return;state=next;if(state.phase==="ended")return finish(state.result);state.message=state.turn===0?"Your turn — select a tile, then discard it.":`${seatTitle(state.turn)} is choosing a discard.`;focusTarget=state.turn===0?"hand":null;commit()}
function scheduleSettlement(){const token=generation;clearTimeout(botTimer);botTimer=setTimeout(()=>{if(token===generation&&state.phase==="claim")settle()},speedDelay[preferences.speed])}
function scheduleBot(){const token=generation;clearTimeout(botTimer);botTimer=setTimeout(()=>{if(token!==generation||state.turn===0)return;if(state.phase==="draw")draw();else if(state.phase==="discard"){if(canSelfDraw(state,state.turn))finish(`${seatTitle(state.turn)} wins by self-draw.`);else discard(state.turn,chooseDiscard(state.players[state.turn].hand))}},speedDelay[preferences.speed])}
function handKeys(event){if(!["ArrowLeft","ArrowRight","ArrowUp","ArrowDown","Home","End","Enter","Escape"].includes(event.key)||state.turn!==0||state.phase!=="discard")return;const tiles=sortTiles(state.players[0].hand);let index=tiles.indexOf(selectedTile);if(event.key==="Escape"){selectedTile=null;event.preventDefault();render();return}if(event.key==="Enter"){if(selectedTile)discard(0,selectedTile);event.preventDefault();return}if(event.key==="Home")index=0;else if(event.key==="End")index=tiles.length-1;else index=(index+(event.key==="ArrowLeft"||event.key==="ArrowUp"?-1:1)+tiles.length)%tiles.length;selectedTile=tiles[index];focusTarget="selected";event.preventDefault();render()}
$("#new-game").addEventListener("click",newGame);["computer-speed","tile-text","reduced-motion"].forEach(id=>$("#"+id).addEventListener("change",event=>{preferences[{"computer-speed":"speed","tile-text":"tileText","reduced-motion":"motion"}[id]]=event.target.value;applyPreferences();savePreferences()}));document.addEventListener("keydown",handKeys);loadPreferences();load();

